import sys

class Appliance:
    def __init__(self, appliance_id, name, power_rating, status):
        self.appliance_id = appliance_id
        self.name = name
        self.power_rating = power_rating
        self.status = status

    def toggle_status(self):
        self.status = "on" if self.status == "off" else "off"

    def get_power_consumption(self):
        return self.power_rating if self.status == "on" else 0

class SmartHome:
    def __init__(self):
        self.appliances = {}

    def add_appliance(self, appliance):
        self.appliances[appliance.appliance_id] = appliance

    def remove_appliance(self, appliance_id):
        if appliance_id in self.appliances:
            del self.appliances[appliance_id]
            return True
        return False

    def toggle_appliance(self, appliance_id):
        if appliance_id in self.appliances:
            self.appliances[appliance_id].toggle_status()
            return True
        return False

    def calculate_total_power(self):
        total = sum(appliance.get_power_consumption() for appliance in self.appliances.values())
        return total

    def is_appliance_on(self, appliance_id):
        if appliance_id in self.appliances:
            return self.appliances[appliance_id].status == "on"
        return None

def parse_power(s):
    """Parse power rating which may be integer or float"""
    if '.' in s:
        return float(s)
    return int(s)

def parse_appliance_line(line):
    """Parse appliance details from line"""
    parts = line.rstrip().split()
    if len(parts) >= 4:
        appliance_id = int(parts[0])
        name = parts[1]
        power_rating = parse_power(parts[2])
        status = parts[3]
        return Appliance(appliance_id, name, power_rating, status)
    return None

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1

    smart_home = SmartHome()

    for _ in range(n):
        if idx < len(data):
            appliance = parse_appliance_line(data[idx])
            if appliance:
                smart_home.add_appliance(appliance)
            idx += 1

    m = int(data[idx])
    idx += 1

    for _ in range(m):
        if idx >= len(data):
            break
        line = data[idx].rstrip()
        idx += 1

        if not line:
            continue

        parts = line.split()
        operation = parts[0].lower() if parts else ""

        if operation == "add" and len(parts) >= 5:
            appliance_id = int(parts[1])
            name = parts[2]
            power_rating = parse_power(parts[3])
            status = parts[4]
            appliance = Appliance(appliance_id, name, power_rating, status)
            smart_home.add_appliance(appliance)
        elif operation == "remove" and len(parts) >= 2:
            appliance_id = int(parts[1])
            if smart_home.remove_appliance(appliance_id):
                print("Appliance removed successfully")
            else:
                print("Appliance not found")
        elif operation == "toggle" and len(parts) >= 2:
            appliance_id = int(parts[1])
            if smart_home.toggle_appliance(appliance_id):
                print("Appliance status toggled")
            else:
                print("Appliance not found")
        elif operation == "calculate" and len(parts) == 1:
            total_power = smart_home.calculate_total_power()
            print(f"Total Power Consumption: {total_power} kW")

if __name__ == "__main__":
    main()
